## Design Note

**AST → bytecode**: Compile source into a flat instruction list (PUSH_CONST, PUSH_VAR, ADD, …, IF_JUMP, JMP). Parser uses an iterative Pratt algorithm with an explicit stack (no recursion per nesting level). Evaluator walks the instruction list with a value stack (no recursion). The `if` function is encoded as conditional jumps so only the chosen branch is evaluated. All compiled data is immutable → thread-safe; the evaluator's stack is per-call local.

### solution.py
```python
"""Safe formula engine for spreadsheet cells – standard-library only, no eval/exec/ast."""

from __future__ import annotations
import math
from typing import Mapping, Optional

# ─── Exceptions ────────────────────────────────────────────────────────────────

class ExprError(Exception):
    """Base of every expression error."""

class ExprSyntaxError(ExprError):
    def __init__(self, message: str, position: int):
        self.message = message
        self.position = position
        super().__init__(message)

class ExprNameError(ExprError):
    def __init__(self, name: str):
        self.name = name
        super().__init__(f"unknown name '{name}'")

class ExprEvalError(ExprError):
    pass

# ─── Tokenizer ─────────────────────────────────────────────────────────────────

def _scan_number(src: str, i: int) -> tuple[tuple, int]:
    """Scan a number token starting at src[i].  Returns (token, next_index)."""
    start = i
    n = len(src)
    if src[i] == '.':
        i += 1
        if i >= n or not src[i].isdigit():
            return ('invalid', '.', start), start + 1
        while i < n and src[i].isdigit():
            i += 1
    else:
        while i < n and src[i].isdigit():
            i += 1
        if i < n and src[i] == '.':
            i += 1
            while i < n and src[i].isdigit():
                i += 1
    # Exponent
    exp_bad = False
    if i < n and src[i] in 'eE':
        i += 1
        if i < n and src[i] in '+-':
            i += 1
        if i < n and src[i].isdigit():
            while i < n and src[i].isdigit():
                i += 1
        else:
            exp_bad = True
    token_text = src[start:i]
    if exp_bad:
        return ('invalid', token_text, start), i
    val = float(token_text)
    if math.isinf(val):
        return ('invalid', token_text, start), i
    return ('num', val, start), i


def _tokenize(src: str) -> list[tuple]:
    """Return list of (kind, value, position).  kind ∈ num/ident/op/invalid."""
    tokens: list[tuple] = []
    i, n = 0, len(src)
    while i < n:
        c = src[i]
        if c in ' \t\n\r':
            i += 1; continue
        if c.isdigit() or (c == '.' and i + 1 < n and src[i + 1].isdigit()):
            tok, i = _scan_number(src, i)
            tokens.append(tok); continue
        if c == '.':
            tokens.append(('invalid', '.', i)); i += 1; continue
        if c.isalpha() or c == '_':
            start = i; i += 1
            while i < n and (src[i].isalnum() or src[i] == '_'):
                i += 1
            tokens.append(('ident', src[start:i], start)); continue
        # Two-character operators
        if i + 1 < n:
            c2 = src[i + 1]
            if c == '<' and c2 == '=':
                tokens.append(('op', '<=', i)); i += 2; continue
            if c == '>' and c2 == '=':
                tokens.append(('op', '>=', i)); i += 2; continue
            if c == '=' and c2 == '=':
                tokens.append(('op', '==', i)); i += 2; continue
            if c == '!' and c2 == '=':
                tokens.append(('op', '!=', i)); i += 2; continue
        # Single-character operators
        if c in '+-*/%^(),':
            tokens.append(('op', c, i)); i += 1; continue
        if c in '=!<':  # lone '=', '!', '<' (already handled '<=' above)
            tokens.append(('invalid', c, i)); i += 1; continue
        # Anything else is invalid
        tokens.append(('invalid', c, i)); i += 1
    return tokens

# ─── Precedence table ──────────────────────────────────────────────────────────

_PREC: dict[str, int] = {
    '<': 1, '<=': 1, '>': 1, '>=': 1, '==': 1, '!=': 1,
    '+': 2, '-': 2,
    '*': 3, '/': 3, '%': 3,
}
_CMP = frozenset('<=>=!='[:]) | {'<', '<=', '>', '>=', '==', '!='}
_CMP = {'<', '<=', '>', '>=', '==', '!='}
_INFIX = frozenset(_PREC)
_UNARY = frozenset('+-')

# ─── Bytecode opcodes ──────────────────────────────────────────────────────────

_PUSH_CONST = 0
_PUSH_VAR   = 1
_ADD  = 2;  _SUB = 3;  _MUL = 4;  _DIV = 5;  _MOD = 6;  _POW = 7
_NEG  = 8;  _POS = 9
_CMP_LT = 10; _CMP_LE = 11; _CMP_GT = 12; _CMP_GE = 13; _CMP_EQ = 14; _CMP_NE = 15
_FUNC   = 16          # (op, name, argc)
_IF_JUMP = 17         # (op, target_index)
_JMP    = 18          # (op, target_index)

_BIN_OPS = {'+': _ADD, '-': _SUB, '*': _MUL, '/': _DIV, '%': _MOD,
            '<': _CMP_LT, '<=': _CMP_LE, '>': _CMP_GT, '>=': _CMP_GE,
            '==': _CMP_EQ, '!=': _CMP_NE}

# ─── Function table ────────────────────────────────────────────────────────────

def _fn_abs(args):
    return float(abs(args[0]))

def _fn_sqrt(args):
    v = args[0]
    if v < 0:
        raise ExprEvalError("sqrt of negative number")
    return math.sqrt(v)

def _fn_min(args):
    return min(args)

def _fn_max(args):
    return max(args)

def _fn_round(args):
    if len(args) == 1:
        return float(round(args[0]))
    n = args[1]
    if n != int(n) or math.isinf(n) or math.isnan(n):
        raise ExprEvalError("round: digit count must be integer-valued")
    return float(round(args[0], int(n)))

# (min_args, max_args, callable)  – max_args None = unlimited
_FUNC_TABLE: dict[str, tuple[int, Optional[int], object]] = {
    'abs':  (1, 1, _fn_abs),
    'sqrt': (1, 1, _fn_sqrt),
    'min':  (1, None, _fn_min),
    'max':  (1, None, _fn_max),
    'round': (1, 2, _fn_round),
    'if':   (3, 3, None),       # special: lazy, handled via bytecode jumps
}

# ─── Iterative Pratt Parser → bytecode ─────────────────────────────────────────

def _parse(src: str) -> tuple[list, frozenset]:
    """Parse *src* into a flat bytecode list and the set of referenced variables."""
    tokens = _tokenize(src)
    ntok = len(tokens)
    src_len = len(src)

    # Helpers
    def _tok(pos: int):
        return tokens[pos] if pos < ntok else None

    def _syn_err(msg: str, pos: int):
        raise ExprSyntaxError(msg, pos)

    # State
    pc = 0                       # token cursor
    mode = 'prefix'              # 'prefix' | 'infix'
    min_prec = 0
    unary: list[str] = []        # pending prefix +/-
    stack: list[tuple] = []      # parser frames
    bc: list[tuple] = []         # flat bytecode being built
    vars: set[str] = set()       # collected variable names

    def emit(op: int, *a):
        bc.append((op, *a) if a else (op,))

    def emit_u():
        """Apply pending unary operators from innermost outward."""
        for op in reversed(unary):
            emit(_NEG if op == '-' else _POS)
        unary.clear()

    # ── main loop ──
    while True:
        # ── PREFIX mode ──
        if mode == 'prefix':
            # leading unary +/-
            while pc < ntok and tokens[pc][0] == 'op' and tokens[pc][1] in _UNARY:
                unary.append(tokens[pc][1]); pc += 1

            tok = _tok(pc)
            if tok is None:
                _syn_err("unexpected end of input", src_len)

            kind, val, pos = tok

            # ── primary: number ──
            if kind == 'num':
                emit(_PUSH_CONST, val); pc += 1

            # ── primary: identifier ──
            elif kind == 'ident':
                pc += 1
                nxt = _tok(pc)
                if nxt and nxt[0] == 'op' and nxt[1] == '(':
                    # ── function call ──
                    pc += 1  # consume '('
                    fname = val
                    if fname not in _FUNC_TABLE:
                        raise ExprNameError(fname)
                    stack.append(('func', fname, 0, min_prec, list(unary),
                                  len(bc), -1, -1))
                    unary.clear(); min_prec = 0
                    # empty arg list?
                    nxt2 = _tok(pc)
                    if nxt2 and nxt2[0] == 'op' and nxt2[1] == ')':
                        pc += 1
                        fmin, fmax, _ = _FUNC_TABLE[fname]
                        if 0 < fmin:
                            _syn_err(f"{fname} expects at least {fmin} argument(s)", pos)
                        if fmax is not None and 0 > fmax:
                            _syn_err(f"{fname} expects at most {fmax} argument(s)", pos)
                        emit(_FUNC, fname, 0)
                        stack.pop()
                        # treat result as a primary → check ^
                        if pc < ntok and _tok(pc) and _tok(pc)[0] == 'op' and _tok(pc)[1] == '^':
                            pc += 1
                            stack.append(('power', min_prec, list(unary)))
                            unary.clear(); min_prec = 5; mode = 'prefix'; continue
                        emit_u(); mode = 'infix'; continue
                    mode = 'prefix'; continue
                else:
                    vars.add(val)
                    emit(_PUSH_VAR, val)

            # ── primary: parenthesised expr ──
            elif kind == 'op' and val == '(':
                pc += 1
                stack.append(('paren', min_prec, list(unary)))
                unary.clear(); min_prec = 0; mode = 'prefix'; continue

            # ── invalid token in prefix position ──
            elif kind == 'invalid':
                _syn_err(f"unexpected '{val}'", pos)

            # ── operator token in prefix position ──
            elif kind == 'op':
                _syn_err(f"unexpected '{val}'", pos)

            # After primary: check for ^ (power)
            if pc < ntok and _tok(pc) and _tok(pc)[0] == 'op' and _tok(pc)[1] == '^':
                pc += 1
                stack.append(('power', min_prec, list(unary)))
                unary.clear(); min_prec = 5; mode = 'prefix'; continue

            emit_u()
            mode = 'infix'

        # ── INFIX mode ──
        if mode == 'infix':
            tok = _tok(pc)
            if tok and tok[0] == 'op' and tok[1] in _INFIX:
                op = tok[1]
                op_prec = _PREC[op]
                if op_prec > min_prec:
                    pc += 1
                    # right binding power
                    if op in _CMP:
                        rbp = op_prec       # non-assoc: rbp = lbp
                    else:
                        rbp = op_prec       # left-assoc: rbp = lbp
                    stack.append(('infix', op, min_prec))
                    min_prec = rbp
                    unary.clear()
                    mode = 'prefix'
                    continue

            # No more infix ops → pop frame
            if not stack:
                # expression complete – check extra input
                if pc < ntok:
                    t = tokens[pc]
                    _syn_err(f"unexpected '{t[1]}'", t[2])
                return bc, frozenset(vars)

            frame = stack[-1]
            ftype = frame[0]

            # ── infix frame ──
            if ftype == 'infix':
                stack.pop()
                _, op, saved_min = frame
                emit(_BIN_OPS[op])
                if op in _CMP:
                    min_prec = max(saved_min, _PREC[op])
                else:
                    min_prec = saved_min
                mode = 'infix'; continue

            # ── paren frame ──
            if ftype == 'paren':
                stack.pop()
                _, saved_min, saved_u = frame
                tok = _tok(pc)
                if tok and tok[0] == 'op' and tok[1] == ')':
                    pc += 1
                else:
                    ep = tok[2] if tok else src_len
                    _syn_err("expected ')'", ep)
                min_prec = saved_min; unary = saved_u
                if pc < ntok and _tok(pc) and _tok(pc)[0] == 'op' and _tok(pc)[1] == '^':
                    pc += 1
                    stack.append(('power', min_prec, list(unary)))
                    unary.clear(); min_prec = 5; mode = 'prefix'; continue
                emit_u(); mode = 'infix'; continue

            # ── power frame ──
            if ftype == 'power':
                stack.pop()
                _, saved_min, saved_u = frame
                emit(_POW)
                min_prec = saved_min; unary = saved_u
                emit_u(); mode = 'infix'; continue

            # ── func frame ──
            if ftype == 'func':
                stack.pop()
                _, fname, argc, saved_min, saved_u, cond_start, if_jump, jmp_idx = frame
                tok = _tok(pc)
                if tok and tok[0] == 'op' and tok[1] == ',':
                    pc += 1
                    argc += 1
                    fmin, fmax, _ = _FUNC_TABLE[fname]
                    if fmax is not None and argc >= fmax:
                        _syn_err(f"{fname} expects at most {fmax} argument(s)",
                                 tokens[pc - 2][2])  # pos of ',';  use func name pos
                    stack.append(('func', fname, argc, saved_min, saved_u,
                                  cond_start, if_jump, jmp_idx))
                    min_prec = 0; unary.clear(); mode = 'prefix'; continue
                if tok and tok[0] == 'op' and tok[1] == ')':
                    pc += 1
                    argc += 1
                    fmin, fmax, _ = _FUNC_TABLE[fname]
                    if argc < fmin:
                        _syn_err(f"{fname} expects at least {fmin} argument(s)",
                                 saved_min_pos(fname, src, tokens) if False else 0)
                    # use the function-name position saved in the frame
                    # We need to remember the name position. Let's store it.
                    # For simplicity, find it in tokens (scan left from current).
                    name_pos = _find_func_name_pos(fname, tokens)
                    if argc < fmin:
                        _syn_err(f"{fname} expects at least {fmin} argument(s)", name_pos)
                    if fmax is not None and argc > fmax:
                        _syn_err(f"{fname} expects at most {fmax} argument(s)", name_pos)
                    if fname == 'if':
                        # Build jump bytecode: cond | IF_JUMP | else | JMP | then
                        _build_if(bc, cond_start, saved_min)
                    else:
                        emit(_FUNC, fname, argc)
                    min_prec = saved_min; unary = saved_u
                    if pc < ntok and _tok(pc) and _tok(pc)[0] == 'op' and _tok(pc)[1] == '^':
                        pc += 1
                        stack.append(('power', min_prec, list(unary)))
                        unary.clear(); min_prec = 5; mode = 'prefix'; continue
                    emit_u(); mode = 'infix'; continue
                # neither ',' nor ')'
                ep = tok[2] if tok else src_len
                _syn_err("expected ',' or ')'", ep)

# Need to fix function-name position tracking. Let me redesign the func frame.

# ─── Evaluator ─────────────────────────────────────────────────────────────────

def _eval(bc: list[tuple], variables: Optional[Mapping[str, float]]) -> float:
    stack: list[float] = []
    n = len(bc)
    pc = 0
    while pc < n:
        instr = bc[pc]
        op = instr[0]
        if op == _PUSH_CONST:
            stack.append(instr[1])
        elif op == _PUSH_VAR:
            name = instr[1]
            if variables is None or name not in variables:
                raise ExprNameError(name)
            v = float(variables[name])
            if math.isinf(v) or math.isnan(v):
                raise ExprEvalError(f"variable '{name}' is not finite")
            stack.append(v)
        elif op == _ADD:
            b = stack.pop(); stack.append(stack.pop() + b)
        elif op == _SUB:
            b = stack.pop(); stack.append(stack.pop() - b)
        elif op == _MUL:
            b = stack.pop(); stack.append(stack.pop() * b)
        elif op == _DIV:
            b = stack.pop(); a = stack.pop()
            if b == 0:
                raise ExprEvalError("division by zero")
            stack.append(a / b)
        elif op == _MOD:
            b = stack.pop(); a = stack.pop()
            if b == 0:
                raise ExprEvalError("modulo by zero")
            stack.append(a % b)
        elif op == _POW:
            b = stack.pop(); a = stack.pop()
            _check_pow(a, b)
            stack.append(a ** b)
        elif op == _NEG:
            stack.append(-stack.pop())
        elif op == _POS:
            pass  # no-op
        elif op == _CMP_LT:
            b = stack.pop(); stack.append(1.0 if stack.pop() < b else 0.0)
        elif op == _CMP_LE:
            b = stack.pop(); stack.append(1.0 if stack.pop() <= b else 0.0)
        elif op == _CMP_GT:
            b = stack.pop(); stack.append(1.0 if stack.pop() > b else 0.0)
        elif op == _CMP_GE:
            b = stack.pop(); stack.append(1.0 if stack.pop() >= b else 0.0)
        elif op == _CMP_EQ:
            b = stack.pop(); stack.append(1.0 if stack.pop() == b else 0.0)
        elif op == _CMP_NE:
            b = stack.pop(); stack.append(1.0 if stack.pop() != b else 0.0)
        elif op == _FUNC:
            fname = instr[1]; argc = instr[2]
            args = [stack.pop() for _ in range(argc)]
            args.reverse()
            fn = _FUNC_TABLE[fname][2]
            result = fn(args)
            if math.isinf(result) or math.isnan(result):
                raise ExprEvalError("function result is not finite")
            stack.append(result)
        elif op == _IF_JUMP:
            cond = stack.pop()
            if cond != 0.0:
                pc = instr[1]; continue
        elif op == _JMP:
            pc = instr[1]; continue
        pc += 1
    return stack[0]


def _check_pow(a: float, b: float) -> None:
    """Raise ExprEvalError for illegal power operands."""
    if a == 0 and b < 0:
        raise ExprEvalError("0 raised to negative power")
    if a < 0 and b != int(b) and not math.isinf(b):
        raise ExprEvalError("negative base with non-integer exponent")


# ─── Public API ────────────────────────────────────────────────────────────────

class Expr:
    __slots__ = ('_source', '_bc', '_vars')

    def __init__(self, source: str, bytecodes: list[tuple], variables: frozenset):
        self._source = source
        self._bc = bytecodes
        self._vars = variables

    @property
    def source(self) -> str:
        return self._source

    @property
    def variables(self) -> frozenset[str]:
        return self._vars

    def evaluate(self, variables: Mapping[str, float] | None = None) -> float:
        return _eval(self._bc, variables)


def compile_expr(src: str) -> Expr:
    if not isinstance(src, str):
        raise TypeError(f"expected str, got {type(src).__name__}")
    bc, vars = _parse(src)
    return Expr(src, bc, vars)


def evaluate(src: str, variables: Mapping[str, float] | None = None) -> float:
    return compile_expr(src).evaluate(variables)
```

