            '<':10,'<=':11,'>':12,'>=':13,'==':14,'!=':15}

_P=0; _V=1; _A=2; _S=3; _M=4; _D=5; _Mo=6; _Pw=7; _N=8; _Po=9
_CL=10; _CL2=11; _CG=12; _CG2=13; _CE=14; _CN=15
_F=16; _IF=17; _JM=18

def _fn_abs(a): return float(abs(a[0]))
def _fn_sqrt(a):
