_FN: dict[str,tuple[int,Optional[int],object]] = {
    'abs':(1,1,_fn_abs),'sqrt':(1,1,_fn_sqrt),
    'min':(1,None,_fn_min),'max':(1,None,_fn_max),
    'round':(1,2,_fn_round),'if':(3,3,None),
