# ─── Iterative Pratt parser → bytecode ─────────────────────────────────────────

def _parse(src: str) -> tuple[list, frozenset]:
    toks = _tokenize(src); nt = len(toks); sl = len(src)
    bc: list = []; vars: set = set()

    pc=0; mode='prefix'; mp=0; unary=[]; stack=[]

    def T(): return toks[pc] if pc<nt else None
    def E(msg,pos): raise ExprSyntaxError(msg,pos)
    def emit(*a): bc.append(a if len(a)>1 else a)
    def emit_u():
        for op in reversed(unary): emit(_N if op=='-' else _Po)
        unary.clear()

