    def __init__(self, source, bytecodes, variables):
        self._source = source; self._bc = bytecodes; self._vars = variables
    @property
    def source(self) -> str: return self._source
    @property
    def variables(self) -> frozenset: return self._vars
    def evaluate(self, variables=None) -> float: return _eval(self._bc, variables)

def compile_expr(src: str) -> Expr:
    if not isinstance(src, str):
        raise TypeError(f"expected str, got {type(src).__name__}")
    bc, v = _parse(src)
    return Expr(src, bc, v)

def evaluate(src: str, variables: Mapping[str, float] | None = None) -> float:
    return compile_expr(src).evaluate(variables)
